-- Konsens V2: notifications, Premium whale alerts and provider connection registry.
create or replace function public.konsens_is_admin(p_user_id uuid default auth.uid()) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.profiles p where p.id=coalesce(p_user_id,auth.uid()) and p.role='admin') $$;
create or replace function public.konsens_is_premium(p_user_id uuid default auth.uid()) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.profiles p where p.id=coalesce(p_user_id,auth.uid()) and (p.subscription_tier='premium' or p.role='admin')) $$;
grant execute on function public.konsens_is_admin(uuid) to authenticated; grant execute on function public.konsens_is_premium(uuid) to authenticated;
create table if not exists public.notification_preferences(user_id uuid primary key references public.profiles(id) on delete cascade,play_enabled boolean not null default true,finance_enabled boolean not null default true,blockchain_enabled boolean not null default true,market_move_points numeric(6,2) not null default 4 check(market_move_points between .5 and 50),asset_move_percent numeric(6,2) not null default 3 check(asset_move_percent between .25 and 50),whale_minimum_eur numeric(18,2) not null default 25000 check(whale_minimum_eur>=0),browser_enabled boolean not null default false,ios_enabled boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
alter table public.notification_preferences enable row level security; drop policy if exists notification_preferences_read_own on public.notification_preferences;drop policy if exists notification_preferences_insert_own on public.notification_preferences;drop policy if exists notification_preferences_update_own on public.notification_preferences;create policy notification_preferences_read_own on public.notification_preferences for select to authenticated using(auth.uid()=user_id);create policy notification_preferences_insert_own on public.notification_preferences for insert to authenticated with check(auth.uid()=user_id);create policy notification_preferences_update_own on public.notification_preferences for update to authenticated using(auth.uid()=user_id) with check(auth.uid()=user_id);grant select,insert,update on public.notification_preferences to authenticated;insert into public.notification_preferences(user_id) select id from public.profiles on conflict(user_id) do nothing;
create or replace function public.seed_notification_preferences() returns trigger language plpgsql security definer set search_path=public as $$begin insert into public.notification_preferences(user_id) values(new.id) on conflict(user_id) do nothing;return new;end$$;drop trigger if exists profiles_seed_notification_preferences on public.profiles;create trigger profiles_seed_notification_preferences after insert on public.profiles for each row execute function public.seed_notification_preferences();
create table if not exists public.notification_events(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id) on delete cascade,kind text not null check(kind in('market_move','asset_move','whale_move','system','premium')),title text not null,body text not null,payload jsonb not null default '{}'::jsonb,dedupe_key text,created_at timestamptz not null default now(),read_at timestamptz);create unique index if not exists notification_events_dedupe_key_idx on public.notification_events(dedupe_key) where dedupe_key is not null;create index if not exists notification_events_user_created_idx on public.notification_events(user_id,created_at desc);alter table public.notification_events enable row level security;drop policy if exists notification_events_read_own on public.notification_events;drop policy if exists notification_events_update_own on public.notification_events;drop policy if exists notification_events_delete_own on public.notification_events;create policy notification_events_read_own on public.notification_events for select to authenticated using(auth.uid()=user_id);create policy notification_events_update_own on public.notification_events for update to authenticated using(auth.uid()=user_id) with check(auth.uid()=user_id);create policy notification_events_delete_own on public.notification_events for delete to authenticated using(auth.uid()=user_id);grant select,update,delete on public.notification_events to authenticated;
create table if not exists public.notification_endpoints(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id) on delete cascade,platform text not null check(platform in('web','ios','watch')),endpoint text,token text,public_key text,auth_secret text,user_agent text,active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(user_id,platform,endpoint));alter table public.notification_endpoints enable row level security;drop policy if exists notification_endpoints_own on public.notification_endpoints;create policy notification_endpoints_own on public.notification_endpoints for all to authenticated using(auth.uid()=user_id) with check(auth.uid()=user_id);grant select,insert,update,delete on public.notification_endpoints to authenticated;
create table if not exists public.provider_connections(provider text primary key,category text not null check(category in('finance','blockchain','ai','billing','advertising','distribution')),display_name text not null,status text not null default 'code_ready' check(status in('live','code_ready','awaiting_secret','disabled')),required_secret_names text[] not null default '{}',public_configuration jsonb not null default '{}'::jsonb,notes text,updated_at timestamptz not null default now());alter table public.provider_connections enable row level security;drop policy if exists provider_connections_admin_read on public.provider_connections;drop policy if exists provider_connections_admin_write on public.provider_connections;create policy provider_connections_admin_read on public.provider_connections for select to authenticated using(public.konsens_is_admin(auth.uid()));create policy provider_connections_admin_write on public.provider_connections for all to authenticated using(public.konsens_is_admin(auth.uid())) with check(public.konsens_is_admin(auth.uid()));grant select,insert,update,delete on public.provider_connections to authenticated;
insert into public.provider_connections(provider,category,display_name,status,required_secret_names,public_configuration,notes) values ('yahoo_beta','finance','Yahoo Finance fallback','live','{}','{"scope":"market quotes + charts","commercial":"beta fallback"}','Fallback actif sans clé. À remplacer prioritairement par le fournisseur contractuel.'),('twelve_data','finance','Twelve Data','awaiting_secret','{"TWELVE_DATA_API_KEY"}','{"scope":"market quotes + time series"}','Adaptateur déjà déployé dans market-data.'),('etherscan','blockchain','Etherscan V2','awaiting_secret','{"ETHERSCAN_API_KEY"}','{"chain":"ethereum","scope":"address transactions"}','Connecteur blockchain-data.'),('blockscout','blockchain','Blockscout Ethereum','code_ready','{}','{"chain":"ethereum","scope":"public explorer fallback"}','Fallback public de transparence EVM.'),('cloudflare_ai','ai','Cloudflare Workers AI','awaiting_secret','{"CLOUDFLARE_API_TOKEN","CLOUDFLARE_ACCOUNT_ID"}','{"scope":"news prediction markets"}','Générateur de marchés côté Worker.'),('stripe','billing','Stripe','awaiting_secret','{"STRIPE_SECRET_KEY","STRIPE_WEBHOOK_SECRET"}','{"price":"4.99 EUR/month","surface":"web"}','Checkout à finaliser avec secrets marchands.'),('storekit','billing','Apple StoreKit','code_ready','{}','{"price":"4.99 EUR/month","surface":"ios"}','Produit App Store Connect requis.'),('konsens_ads','advertising','Konsens Ads','live','{}','{"scope":"first-party contextual ads"}','Régie first-party active.') on conflict(provider) do update set category=excluded.category,display_name=excluded.display_name,status=excluded.status,required_secret_names=excluded.required_secret_names,public_configuration=excluded.public_configuration,notes=excluded.notes,updated_at=now();
drop policy if exists wallet_follows_own_insert on public.wallet_follows;drop policy if exists wallet_follows_own_update on public.wallet_follows;create policy wallet_follows_own_insert on public.wallet_follows for insert to authenticated with check(auth.uid()=user_id and public.konsens_is_premium(auth.uid()) and (select count(*) from public.wallet_follows f where f.user_id=auth.uid())<10);create policy wallet_follows_own_update on public.wallet_follows for update to authenticated using(auth.uid()=user_id and public.konsens_is_premium(auth.uid())) with check(auth.uid()=user_id and public.konsens_is_premium(auth.uid()));
drop function if exists public.get_whale_leaderboard(integer);create function public.get_whale_leaderboard(p_limit integer default 25) returns table(id uuid,chain text,address text,display_name text,attribution_type text,confidence_score smallint,attribution_source_url text,observable_value_eur numeric,volume_30d_eur numeric,transactions_30d bigint,last_activity timestamptz) language sql stable security definer set search_path=public as $$select w.id,w.chain,w.address,w.display_name,w.attribution_type,w.confidence_score,w.attribution_source_url,w.observable_value_eur,coalesce(sum(abs(e.estimated_value_eur)) filter(where e.block_time>=now()-interval '30 days'),0)::numeric,count(e.id) filter(where e.block_time>=now()-interval '30 days')::bigint,max(e.block_time) from public.public_wallets w left join public.wallet_events e on e.wallet_id=w.id where w.is_active=true group by w.id,w.chain,w.address,w.display_name,w.attribution_type,w.confidence_score,w.attribution_source_url,w.observable_value_eur order by coalesce(w.observable_value_eur,0) desc,9 desc limit greatest(1,least(coalesce(p_limit,25),50))$$;grant execute on function public.get_whale_leaderboard(integer) to authenticated;
create or replace function public.set_wallet_alert(p_wallet_id uuid,p_minimum_alert_eur numeric,p_enabled boolean default true) returns void language plpgsql security definer set search_path=public as $$begin if not public.konsens_is_premium(auth.uid()) then raise exception 'premium_required';end if;update public.wallet_follows set minimum_alert_eur=greatest(coalesce(p_minimum_alert_eur,0),0),notifications_enabled=coalesce(p_enabled,true) where user_id=auth.uid() and wallet_id=p_wallet_id;if not found then raise exception 'wallet_not_followed';end if;end$$;grant execute on function public.set_wallet_alert(uuid,numeric,boolean) to authenticated;
create or replace function public.notify_market_movement() returns trigger language plpgsql security definer set search_path=public as $$declare previous_probability numeric;delta_points numeric;r record;q text;begin select h.yes_probability into previous_probability from public.market_probability_history h where h.market_id=new.market_id and h.observed_at<new.observed_at order by h.observed_at desc limit 1;if previous_probability is null then return new;end if;delta_points:=abs(new.yes_probability-previous_probability)*100;select question into q from public.markets where id=new.market_id;for r in select mw.user_id,np.market_move_points from public.market_watchlist mw join public.notification_preferences np on np.user_id=mw.user_id where mw.market_id=new.market_id and np.play_enabled=true and delta_points>=np.market_move_points loop insert into public.notification_events(user_id,kind,title,body,payload,dedupe_key) values(r.user_id,'market_move','Un marché bouge',coalesce(q,'Marché suivi')||' · '||round(delta_points,1)||' pt',jsonb_build_object('market_id',new.market_id,'probability',new.yes_probability,'delta_points',delta_points,'route','play'),'market:'||r.user_id||':'||new.market_id||':'||date_trunc('minute',new.observed_at)::text) on conflict(dedupe_key) where dedupe_key is not null do nothing;end loop;return new;end$$;drop trigger if exists trg_notify_market_movement on public.market_probability_history;create trigger trg_notify_market_movement after insert on public.market_probability_history for each row execute function public.notify_market_movement();
create or replace function public.notify_asset_movement() returns trigger language plpgsql security definer set search_path=public as $$declare previous_price numeric;delta_percent numeric;r record;sym text;begin select h.price into previous_price from public.price_history h where h.asset_id=new.asset_id and h.observed_at<new.observed_at order by h.observed_at desc limit 1;if previous_price is null or previous_price=0 then return new;end if;delta_percent:=abs((new.price-previous_price)/previous_price*100);select symbol into sym from public.assets where id=new.asset_id;for r in select aw.user_id,np.asset_move_percent from public.asset_watchlist aw join public.notification_preferences np on np.user_id=aw.user_id where aw.asset_id=new.asset_id and np.finance_enabled=true and delta_percent>=np.asset_move_percent loop insert into public.notification_events(user_id,kind,title,body,payload,dedupe_key) values(r.user_id,'asset_move',coalesce(sym,'Actif')||' bouge',coalesce(sym,'Actif suivi')||' · '||round(delta_percent,2)||' % depuis le dernier point',jsonb_build_object('asset_id',new.asset_id,'price',new.price,'delta_percent',delta_percent,'route','finance'),'asset:'||r.user_id||':'||new.asset_id||':'||date_trunc('minute',new.observed_at)::text) on conflict(dedupe_key) where dedupe_key is not null do nothing;end loop;return new;end$$;drop trigger if exists trg_notify_asset_movement on public.price_history;create trigger trg_notify_asset_movement after insert on public.price_history for each row execute function public.notify_asset_movement();
create or replace function public.notify_whale_movement() returns trigger language plpgsql security definer set search_path=public as $$declare r record;wallet_name text;amount numeric;begin amount:=abs(coalesce(new.estimated_value_eur,0));select display_name into wallet_name from public.public_wallets where id=new.wallet_id;for r in select f.user_id,greatest(coalesce(f.minimum_alert_eur,0),coalesce(np.whale_minimum_eur,0)) threshold from public.wallet_follows f join public.notification_preferences np on np.user_id=f.user_id where f.wallet_id=new.wallet_id and f.notifications_enabled=true and np.blockchain_enabled=true and public.konsens_is_premium(f.user_id) loop if amount>=r.threshold then insert into public.notification_events(user_id,kind,title,body,payload,dedupe_key) values(r.user_id,'whale_move','Mouvement blockchain',coalesce(wallet_name,'Portefeuille suivi')||' · '||round(amount,0)||' € · '||coalesce(new.asset_symbol,'actif'),jsonb_build_object('wallet_id',new.wallet_id,'event_id',new.id,'amount_eur',amount,'asset',new.asset_symbol,'direction',new.direction,'explorer_url',new.explorer_url,'route','blockchain'),'wallet:'||r.user_id||':'||new.id) on conflict(dedupe_key) where dedupe_key is not null do nothing;end if;end loop;return new;end$$;drop trigger if exists trg_notify_whale_movement on public.wallet_events;create trigger trg_notify_whale_movement after insert on public.wallet_events for each row execute function public.notify_whale_movement();
do $$begin if not exists(select 1 from pg_publication_tables where pubname='supabase_realtime' and schemaname='public' and tablename='notification_events') then alter publication supabase_realtime add table public.notification_events;end if;end$$;
